<?php require_once '_bootstrap.php';require_admin();$db=admin_db();$monthly=$db->query("SELECT DATE_FORMAT(created_at,'%Y-%m') month,COUNT(*) bookings,SUM(total_amount) value,SUM(payment_status='paid') paid FROM bookings GROUP BY month ORDER BY month DESC LIMIT 12");$destinations=$db->query('SELECT destination,COUNT(*) bookings,SUM(people) travellers,SUM(total_amount) value FROM bookings GROUP BY destination ORDER BY bookings DESC LIMIT 10');$pageTitle='Reports';include '_header.php';?><div class="page-head"><div><span>India tourism management information</span><h1>Reports</h1></div><button class="primary-btn" onclick="window.print()"><i class="fa-solid fa-print"></i>Print report</button></div><div class="report-grid"><section class="panel"><div class="panel-head"><h2>Monthly performance</h2></div><div class="table-wrap"><table><thead><tr><th>Month</th><th>Bookings</th><th>Paid</th><th>Booked value (INR)</th></tr></thead><tbody><?php while($r=$monthly->fetch_assoc()):?><tr><td><?php echo e($r['month']);?></td><td><?php echo (int)$r['bookings'];?></td><td><?php echo (int)$r['paid'];?></td><td><?php echo inr($r['value']);?></td></tr><?php endwhile;?></tbody></table></div></section><section class="panel"><div class="panel-head"><h2>Top Indian destinations</h2></div><div class="table-wrap"><table><thead><tr><th>Destination</th><th>Bookings</th><th>Travellers</th><th>Value (INR)</th></tr></thead><tbody><?php while($r=$destinations->fetch_assoc()):?><tr><td><?php echo e($r['destination']);?></td><td><?php echo (int)$r['bookings'];?></td><td><?php echo (int)$r['travellers'];?></td><td><?php echo inr($r['value']);?></td></tr><?php endwhile;?></tbody></table></div></section></div><?php include '_footer.php';?>
